00053 IbcHashMap::IbcHashMap()
00054 {
00055   m_picWidth = 0;
00056   m_picHeight = 0;
00057   m_pos2Hash = NULL;
00058   m_computeCrc32c = xxComputeCrc32c16bit;
00059 
00060 #if ENABLE_SIMD_OPT_IBC
00061 #ifdef TARGET_SIMD_X86
00062   initIbcHashMapX86();
00063 #endif
00064 #endif
00065 
00066 }
00067 
00068 IbcHashMap::~IbcHashMap()
00069 {
00070   destroy();
00071 }
00072 
00073 void IbcHashMap::init(const int picWidth, const int picHeight)
00074 {
00075   if (picWidth != m_picWidth || picHeight != m_picHeight)
00076   {
00077     destroy();
00078   }
00079 
00080   m_picWidth = picWidth;
00081   m_picHeight = picHeight;
00082   m_pos2Hash = new unsigned int*[m_picHeight];
00083   m_pos2Hash[0] = new unsigned int[m_picWidth * m_picHeight];
00084   for (int n = 1; n < m_picHeight; n++)
00085   {
00086     m_pos2Hash[n] = m_pos2Hash[n - 1] + m_picWidth;
00087   }
00088 }
00089 
00090 void IbcHashMap::destroy()
00091 {
00092   if (m_pos2Hash != NULL)
00093   {
00094     if (m_pos2Hash[0] != NULL)
00095     {
00096       delete[] m_pos2Hash[0];
00097     }
00098     delete[] m_pos2Hash;
00099   }
00100   m_pos2Hash = NULL;
00101 }
