00171 uint32_t IbcHashMap::xxComputeCrc32c16bit(uint32_t crc, const Pel pel)
00172 {
00173   const void *buf = &pel;
00174   const uint8_t *p = (const uint8_t *)buf;
00175   size_t size = 2;
00176 
00177   while (size--)
00178   {
00179     crc = crc32Table[(crc ^ *p++) & 0xff] ^ (crc >> 8);
00180   }
00181 
00182   return crc;
00183 }
00184 // CRC calculation in C code
00186 
00187 unsigned int IbcHashMap::xxCalcBlockHash(const Pel* pel, const int stride, const int width, const int height, unsigned int crc)
00188 {
00189   for (int y = 0; y < height; y++)
00190   {
00191     for (int x = 0; x < width; x++)
00192     {
00193       crc = m_computeCrc32c(crc, pel[x]);
00194     }
00195     pel += stride;
00196   }
00197   return crc;
00198 }
00199 
00200 template<ChromaFormat chromaFormat>
00201 void IbcHashMap::xxBuildPicHashMap(const PelUnitBuf& pic)
00202 {
00203   const int chromaScalingX = getChannelTypeScaleX(CHANNEL_TYPE_CHROMA, chromaFormat);
00204   const int chromaScalingY = getChannelTypeScaleY(CHANNEL_TYPE_CHROMA, chromaFormat);
00205   const int chromaMinBlkWidth = MIN_PU_SIZE >> chromaScalingX;
00206   const int chromaMinBlkHeight = MIN_PU_SIZE >> chromaScalingY;
00207   const Pel* pelY = NULL;
00208   const Pel* pelCb = NULL;
00209   const Pel* pelCr = NULL;
00210 
00211   Position pos;
00212   for (pos.y = 0; pos.y + MIN_PU_SIZE <= pic.Y().height; pos.y++)
00213   {
00214     // row pointer
00215     pelY = pic.Y().bufAt(0, pos.y);
00216     if (chromaFormat != CHROMA_400)
00217     {
00218       int chromaY = pos.y >> chromaScalingY;
00219       pelCb = pic.Cb().bufAt(0, chromaY);
00220       pelCr = pic.Cr().bufAt(0, chromaY);
00221     }
00222 
00223     for (pos.x = 0; pos.x + MIN_PU_SIZE <= pic.Y().width; pos.x++)
00224     {
00225       // 0x1FF is just an initial value
00226       unsigned int hashValue = 0x1FF;
00227 
00228       // luma part
00229       hashValue = xxCalcBlockHash(&pelY[pos.x], pic.Y().stride, MIN_PU_SIZE, MIN_PU_SIZE, hashValue);
00230 
00231       // chroma part
00232       if (chromaFormat != CHROMA_400)
00233       {
00234         int chromaX = pos.x >> chromaScalingX;
00235         hashValue = xxCalcBlockHash(&pelCb[chromaX], pic.Cb().stride, chromaMinBlkWidth, chromaMinBlkHeight, hashValue);
00236         hashValue = xxCalcBlockHash(&pelCr[chromaX], pic.Cr().stride, chromaMinBlkWidth, chromaMinBlkHeight, hashValue);
00237       }
00238 
00239       // hash table
00240       m_hash2Pos[hashValue].push_back(pos);
00241       m_pos2Hash[pos.y][pos.x] = hashValue;
00242     }
00243   }
00244 }
00245 
00246 void IbcHashMap::rebuildPicHashMap(const PelUnitBuf& pic)
00247 {
00248   m_hash2Pos.clear();
00249 
00250   switch (pic.chromaFormat)
00251   {
00252   case CHROMA_400:
00253     xxBuildPicHashMap<CHROMA_400>(pic);
00254     break;
00255   case CHROMA_420:
00256     xxBuildPicHashMap<CHROMA_420>(pic);
00257     break;
00258   case CHROMA_422:
00259     xxBuildPicHashMap<CHROMA_422>(pic);
00260     break;
00261   case CHROMA_444:
00262     xxBuildPicHashMap<CHROMA_444>(pic);
00263     break;
00264   default:
00265     THROW("invalid chroma fomat");
00266     break;
00267   }
00268 }
00269 
00270 bool IbcHashMap::ibcHashMatch(const Area& lumaArea, std::vector<Position>& cand, const CodingStructure& cs, const int maxCand, const int searchRange4SmallBlk)
00271 {
00272   cand.clear();
00273 
00274   // find the block with least candidates
00275   size_t minSize = MAX_UINT;
00276   unsigned int targetHashOneBlock = 0;
00277   Position targetBlockOffsetInCu(0, 0);
00278   for (SizeType y = 0; y < lumaArea.height && minSize > 1; y += MIN_PU_SIZE)
00279   {
00280     for (SizeType x = 0; x < lumaArea.width && minSize > 1; x += MIN_PU_SIZE)
00281     {
00282       unsigned int hash = m_pos2Hash[lumaArea.pos().y + y][lumaArea.pos().x + x];
00283       if (m_hash2Pos[hash].size() < minSize)
00284       {
00285         minSize = m_hash2Pos[hash].size();
00286         targetHashOneBlock = hash;
00287         targetBlockOffsetInCu.repositionTo(Position(x, y));
00288       }
00289     }
00290   }
00291 
00292   if (m_hash2Pos[targetHashOneBlock].size() > 1)
00293   {
00294     std::vector<Position>& candOneBlock = m_hash2Pos[targetHashOneBlock];
00295 
00296     // check whether whole block match
00297     for (std::vector<Position>::iterator refBlockPos = candOneBlock.begin(); refBlockPos != candOneBlock.end(); refBlockPos++)
00298     {
00299       Position topLeft = refBlockPos->offset(-targetBlockOffsetInCu.x, -targetBlockOffsetInCu.y);
00300       Position bottomRight = topLeft.offset(lumaArea.width - 1, lumaArea.height - 1);
00301       bool wholeBlockMatch = true;
00302       if (lumaArea.width > MIN_PU_SIZE || lumaArea.height > MIN_PU_SIZE)
00303       {
00304         if (!cs.isDecomp(bottomRight, CHANNEL_TYPE_LUMA) || bottomRight.x >= m_picWidth || bottomRight.y >= m_picHeight || topLeft.x < 0 || topLeft.y < 0)
00305         {
00306           continue;
00307         }
00308         for (SizeType y = 0; y < lumaArea.height && wholeBlockMatch; y += MIN_PU_SIZE)
00309         {
00310           for (SizeType x = 0; x < lumaArea.width && wholeBlockMatch; x += MIN_PU_SIZE)
00311           {
00312             // whether the reference block and current block has the same hash
00313             wholeBlockMatch &= (m_pos2Hash[lumaArea.pos().y + y][lumaArea.pos().x + x] == m_pos2Hash[topLeft.y + y][topLeft.x + x]);
00314           }
00315         }
00316       }
00317       else
00318       {
00319         CHECK(topLeft != *refBlockPos, "4x4 target block should not have offset!");
00320         if (abs(topLeft.x - lumaArea.x) > searchRange4SmallBlk || abs(topLeft.y - lumaArea.y) > searchRange4SmallBlk || !cs.isDecomp(bottomRight, CHANNEL_TYPE_LUMA))
00321         {
00322           continue;
00323         }
00324       }
00325       if (wholeBlockMatch)
00326       {
00327         cand.push_back(topLeft);
00328         if (cand.size() > maxCand)
00329         {
00330           break;
00331         }
00332       }
00333     }
00334   }
00335 
00336   return cand.size() > 0;
00337 }
00338 
00339 int IbcHashMap::getHashHitRatio(const Area& lumaArea)
00340 {
00341   int maxX = std::min((int)(lumaArea.x + lumaArea.width), m_picWidth);
00342   int maxY = std::min((int)(lumaArea.y + lumaArea.height), m_picHeight);
00343   int hit = 0, total = 0;
00344   for (int y = lumaArea.y; y < maxY; y += MIN_PU_SIZE)
00345   {
00346     for (int x = lumaArea.x; x < maxX; x += MIN_PU_SIZE)
00347     {
00348       const unsigned int hash = m_pos2Hash[y][x];
00349       hit += (m_hash2Pos[hash].size() > 1);
00350       total++;
00351     }
00352   }
00353   return 100 * hit / total;
00354 }
00355 
00356 int IbcHashMap::calHashBlkMatchPerc(const Area& lumaArea)
00357 {
00358   int maxX = std::min((int)(lumaArea.x + lumaArea.width), m_picWidth);
00359   int maxY = std::min((int)(lumaArea.y + lumaArea.height), m_picHeight);
00360   int          maxUsage[100];
00361   unsigned int mostSelHash[100];
00362 
00363   static   int numExcludedHashValue = 36;
00364 
00365   for (int i = 0; i < numExcludedHashValue; i++)
00366   {
00367     maxUsage[i] = 0;
00368     mostSelHash[i] = 0;
00369   }
00370 
00371   for (std::unordered_map<unsigned int, std::vector<Position>>::iterator it = m_hash2Pos.begin(); it != m_hash2Pos.end(); ++it)
00372   {
00373     unsigned int hash = it->first;
00374     int usage = (int)it->second.size();
00375     assert(usage == m_hash2Pos[hash].size());
00376 
00377     int insertPos = -1;
00378     for (insertPos = 0; insertPos < numExcludedHashValue; insertPos++)
00379     {
00380       if (usage > maxUsage[insertPos])
00381       {
00382         break;
00383       }
00384     }
00385     assert(insertPos <= numExcludedHashValue);
00386 
00387     if (insertPos < numExcludedHashValue)
00388     {
00389       for (int i = (numExcludedHashValue - 1); i >= (insertPos + 1); i--)
00390       {
00391         maxUsage[i] = maxUsage[i - 1];
00392         mostSelHash[i] = mostSelHash[i - 1];
00393       }
00394       maxUsage[insertPos] = usage;
00395       mostSelHash[insertPos] = hash;
00396     }
00397   }
00398 
00399   int hit = 0, total = 0;
00400   for (int y = lumaArea.y; y < maxY; y += MIN_PU_SIZE)
00401   {
00402     for (int x = lumaArea.x; x < maxX; x += MIN_PU_SIZE)
00403     {
00404       unsigned int hash = m_pos2Hash[y][x];
00405 
00406       bool excludedHash = false;
00407       for (int i = 0; i < numExcludedHashValue && !excludedHash; i++)
00408       {
00409         if (hash == mostSelHash[i])
00410         {
00411           excludedHash = true;
00412         }
00413       }
00414 
00415       if (excludedHash)
00416       {
00417         continue;
00418       }
00419 
00420       hit += (m_hash2Pos[hash].size() > 1);
00421       total++;
00422     }
00423   }
00424 
00425   if (total == 0)
00426   {
00427     return 0;
00428   }
00429   else
00430   {
00431     return 100 * hit / total;
00432   }
00433 }
